package org.cloudburstmc.protocol.bedrock.codec.v924.serializer;
import io.netty.buffer.ByteBuf; import lombok.AccessLevel; import lombok.RequiredArgsConstructor; import org.cloudburstmc.math.vector.Vector3f; import org.cloudburstmc.protocol.bedrock.codec.BedrockCodecHelper; import org.cloudburstmc.protocol.bedrock.codec.BedrockPacketSerializer; import org.cloudburstmc.protocol.bedrock.data.camera.*; import org.cloudburstmc.protocol.bedrock.packet.CameraSplinePacket; import java.util.*;
@RequiredArgsConstructor(access=AccessLevel.PROTECTED) public class CameraSplineSerializer_v924 implements BedrockPacketSerializer<CameraSplinePacket>{public static final CameraSplineSerializer_v924 INSTANCE=new CameraSplineSerializer_v924();public void serialize(ByteBuf b,BedrockCodecHelper h,CameraSplinePacket p){h.writeArray(b,p.getSplines(),(buf,s)->{h.writeString(buf,s.getName());buf.writeFloatLE(s.getInstruction().getTotalTime());h.writeString(buf,s.getInstruction().getType().getSerializeName());h.writeArray(buf,s.getInstruction().getCurve(),h::writeVector3f);h.writeArray(buf,s.getInstruction().getProgressKeyFrames(),(x,f)->{x.writeFloatLE(f.getValue());x.writeFloatLE(f.getTime());h.writeString(x,f.getEase().getSerializeName());});h.writeArray(buf,s.getInstruction().getRotationOption(),(x,r)->{h.writeVector3f(x,r.getKeyFrameValues());x.writeFloatLE(r.getKeyFrameTimes());h.writeString(x,r.getEase().getSerializeName());});});}public void deserialize(ByteBuf b,BedrockCodecHelper h,CameraSplinePacket p){List<CameraSplineDefinition>s=new ArrayList<>();h.readArray(b,s,(buf,x)->{String n=h.readString(buf);float t=buf.readFloatLE();CameraSplineType ty=CameraSplineType.fromName(h.readString(buf));List<Vector3f>c=new ArrayList<>();h.readArray(buf,c,h::readVector3f);List<CameraSplineInstruction.SplineProgressOption>pk=new ArrayList<>();h.readArray(buf,pk,y->new CameraSplineInstruction.SplineProgressOption(y.readFloatLE(),y.readFloatLE(),CameraEase.fromName(h.readString(y))));List<CameraSplineInstruction.SplineRotationOption>ro=new ArrayList<>();h.readArray(buf,ro,y->{Vector3f v=h.readVector3f(y);float kt=y.readFloatLE();return new CameraSplineInstruction.SplineRotationOption(v,kt,CameraEase.fromName(h.readString(y)));});return new CameraSplineDefinition(n,new CameraSplineInstruction(t,ty,c,pk,ro));});p.setSplines(s);}}
